import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { unregisterDeviceHandler } from "../handlers/unregisterDeviceHandler";
import type { ApiError } from "../runtime/client";
import type { UserDeviceTokenEntityType } from "../types/UserDeviceTokenEntityType";

type Data = Awaited<ReturnType<typeof unregisterDeviceHandler>>;
type Vars = UserDeviceTokenEntityType;

export function useUnregisterDevice(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => unregisterDeviceHandler(vars),
    ...options,
  });
}
